package chat.oldy;
public final class YouTubeLinkCheck {
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 public static void main(String[] args){String id="AbCdEf_1234",list="PL1234567890ABCDEFG";String[] urls={"https://youtube.com/watch?v="+id,"https://www.youtube.com/watch?v="+id+"&feature=share","https://m.youtube.com/watch?v="+id,"https://music.youtube.com/watch?v="+id,"https://youtu.be/"+id,"https://youtu.be/"+id+"?t=12","https://www.youtube.com/shorts/"+id,"https://www.youtube.com/live/"+id,"https://www.youtube.com/embed/"+id,"youtube.com/watch?v="+id,"https://YOUTUBE.COM/watch?v="+id+"&list="+list,"https://youtu.be/"+id+"?t=1h2m3s"};for(String url:urls){YouTubeLinkDetector.Target t=YouTubeLinkDetector.parse(url);check(t!=null&&t.videoId.equals(id),"Not recognized: "+url);}check(YouTubeLinkDetector.parse(urls[11]).startSeconds==3723,"Timestamp lost");YouTubeLinkDetector.Target playlist=YouTubeLinkDetector.parse("https://www.youtube.com/playlist?list="+list);check(playlist!=null&&playlist.videoId.isEmpty()&&playlist.playlistId.equals(list),"Playlist missing");check(YouTubeLinkDetector.first("Video: (https://youtu.be/"+id+").")!=null,"Punctuation not handled");for(String bad:new String[]{"https://youtube.com.evil.example/watch?v="+id,"https://youtube.com@evil.example/watch?v="+id,"https://youtube.com:8080/watch?v="+id,"javascript:alert(1)","https://youtube.com/watch?v=short","https://youtu.be/"+id+"/extra","https://youtube.com/watch?v="+id+"&v=Other_Id_00"})check(YouTubeLinkDetector.parse(bad)==null,"Unsafe URL accepted");System.out.println("OLDY_YOUTUBE_LINKS_PASS: 12 URL forms, playlist, timestamps, punctuation, spoof and injection rejection");}
}
